package ir
import("encoding/json";"os";"os/exec";"path/filepath";"testing")
func TestInputAttachmentProcessCheckpoint(t *testing.T){phase:=os.Getenv("INPUT_ATTACHMENT_PHASE");if phase!=""{original,err:=os.ReadFile(os.Getenv("INPUT_ATTACHMENT_C_WIRE"));if err!=nil||!ValidMessage(original){t.Fatal("C canonical source invalid",err)};var source Message;if !Decode(original,&source){t.Fatal("source decode")};path:=os.Getenv("INPUT_ATTACHMENT_CHECKPOINT");if phase=="writer"{h:=HistoryEvent{Scope:"primary",Phase:"message",Index:0,Message:original};raw,err:=json.Marshal(h);if err!=nil||!ValidHistoryEvent(raw){t.Fatal("checkpoint invalid")};if err=os.WriteFile(path,raw,0600);err!=nil{t.Fatal(err)};return};raw,err:=os.ReadFile(path);var h HistoryEvent;var loaded Message;if err!=nil||!ValidHistoryEvent(raw)||!Decode(raw,&h)||!Decode(h.Message,&loaded)||!InputAttachmentsPreserved([]Message{source},[]Message{loaded}){t.Fatal("restart/checkpoint lost pair",err)};if loaded.Blocks[0].InputAttachment.Opaque!=source.Blocks[0].InputAttachment.Opaque{t.Fatal("opaque bytes changed")};return}
 if os.Getenv("INPUT_ATTACHMENT_C_WIRE")==""{t.Skip("explicit cross-language fixture file required")};exe,err:=os.Executable();if err!=nil{t.Fatal(err)};checkpoint:=filepath.Join(t.TempDir(),"checkpoint.json");for _,phase:=range []string{"writer","reader"}{cmd:=exec.Command(exe,"-test.run=^TestInputAttachmentProcessCheckpoint$","-test.v");cmd.Env=append(os.Environ(),"INPUT_ATTACHMENT_PHASE="+phase,"INPUT_ATTACHMENT_CHECKPOINT="+checkpoint);out,err:=cmd.CombinedOutput();if err!=nil{t.Fatal(phase,err,string(out))}}
}
